import React from 'react';
import BannerArea from '../components/Homepage/Header/BannerArea';
import UniversitySection from "../components/Homepage/University/UniveristyArea";
import AboutArea from "../components/Homepage/About/AboutArea";
import Navbar from "../components/Homepage/Header/Navbar";
import Footer from "../components/Homepage/Footer";

function Home(props) {
    const {professorList, onChangeProfessor, professor} = props;
    return (
        <>
            <div>
                <Navbar isHome={true}/>
                <BannerArea professorList={professorList} onChangeProfessor={onChangeProfessor} professor={professor}/>
                <AboutArea/>
                <UniversitySection/>
                <Footer/>
            </div>

        </>
    );
}

export default Home;
